; VPy M6809 Assembly (Vectrex)
; ROM: 32768 bytes


    ORG $0000

;***************************************************************************
; DEFINE SECTION
;***************************************************************************
    INCLUDE "VECTREX.I"

;***************************************************************************
; CARTRIDGE HEADER
;***************************************************************************
    FCC "g GCE 2025"
    FCB $80                 ; String terminator
    FDB music1              ; Music pointer
    FCB $F8,$50,$20,$BB     ; Height, Width, Rel Y, Rel X
    FCC "VREC PLAYER"
    FCB $80                 ; String terminator
    FCB 0                   ; End of header

;***************************************************************************
; CODE SECTION
;***************************************************************************

START:
    LDA #$D0
    TFR A,DP        ; Set Direct Page for BIOS
    CLR $C80E        ; Initialize Vec_Prev_Btns
    LDA #$80
    STA VIA_t1_cnt_lo
    LDX #Vec_Default_Stk ; Same stack as BIOS default ($CBEA)
    TFR X,S
    LDS #$CFFF       ; Stack -> top of Vectrex 2KB RAM (avoids user var collision)

    ; Initialize bank tracking vars to 0 (prevents spurious $DF00 writes)
    LDA #0
    STA >CURRENT_ROM_BANK   ; Bank 0 is always active at boot
    JMP MAIN

;***************************************************************************
; === RAM VARIABLE DEFINITIONS ===
;***************************************************************************
RESULT               EQU $C880+$00   ; Main result temporary (2 bytes)
TMPVAL               EQU $C880+$02   ; Temporary value storage (alias for RESULT) (2 bytes)
TMPPTR               EQU $C880+$04   ; Temporary pointer (2 bytes)
TMPPTR2              EQU $C880+$06   ; Temporary pointer 2 (2 bytes)
VPY_MOVE_X           EQU $C880+$08   ; MOVE() current X offset (signed byte, 0 by default) (1 bytes)
VPY_MOVE_Y           EQU $C880+$09   ; MOVE() current Y offset (signed byte, 0 by default) (1 bytes)
TEMP_YX              EQU $C880+$0A   ; Temporary Y/X coordinate storage (2 bytes)
BTN_PREV_STATE       EQU $C880+$0C   ; Button edge-detection: holds bit 7,6,5,4 = prev press state for btn 1,2,3,4 (1 bytes)
BTN_RAW              EQU $C880+$0D   ; Raw PSG reg 14 (active-LOW: 0=pressed, 1=released) - Vectorblade pattern (1 bytes)
DRAW_VEC_INTENSITY   EQU $C880+$0E   ; Vector intensity override (0=use vector data) (1 bytes)
DRAW_REC_PTR         EQU $C880+$0F   ; DRAW_RECORDING: _<NAME>_VREC header base (2 bytes)
DRAW_REC_FRAME       EQU $C880+$11   ; DRAW_RECORDING: caller frame counter (i16, non-negative) (2 bytes)
DRAW_REC_X           EQU $C880+$13   ; DRAW_RECORDING: center X (i8) (1 bytes)
DRAW_REC_Y           EQU $C880+$14   ; DRAW_RECORDING: center Y (i8) (1 bytes)
DRAW_REC_SCALE       EQU $C880+$15   ; DRAW_RECORDING: scale 0-128 (128=100%) (1 bytes)
DRAW_REC_SEGCNT      EQU $C880+$16   ; DRAW_RECORDING: remaining chain count in frame (2 bytes)
DRAW_REC_SEGPTR      EQU $C880+$18   ; DRAW_RECORDING: current chain/delta pointer (survives BIOS calls) (2 bytes)
DRAW_REC_CHAIN_SEGS  EQU $C880+$1A   ; DRAW_RECORDING: remaining deltas in current chain (1 bytes)
DRAW_REC_SX0         EQU $C880+$1B   ; DRAW_RECORDING: scaled+centered x0 (i8) (1 bytes)
DRAW_REC_SY0         EQU $C880+$1C   ; DRAW_RECORDING: scaled+centered y0 (i8) (1 bytes)
DRAW_REC_SX1         EQU $C880+$1D   ; DRAW_RECORDING: scaled+centered x1 (i8) (1 bytes)
DRAW_REC_SY1         EQU $C880+$1E   ; DRAW_RECORDING: scaled+centered y1 (i8) (1 bytes)
DRAW_REC_I           EQU $C880+$1F   ; DRAW_RECORDING: per-segment intensity (u8) (1 bytes)
DRAW_REC_TMP16       EQU $C880+$20   ; DRAW_RECORDING: 16-bit scratch for clamped coord/delta math (2 bytes)
DRAW_LINE_ARGS       EQU $C880+$22   ; DRAW_LINE argument buffer (x0,y0,x1,y1,intensity) (10 bytes)
VLINE_DX_16          EQU $C880+$2C   ; DRAW_LINE dx (16-bit) (2 bytes)
VLINE_DY_16          EQU $C880+$2E   ; DRAW_LINE dy (16-bit) (2 bytes)
VLINE_DX             EQU $C880+$30   ; DRAW_LINE dx clamped (8-bit) (1 bytes)
VLINE_DY             EQU $C880+$31   ; DRAW_LINE dy clamped (8-bit) (1 bytes)
VLINE_DY_REMAINING   EQU $C880+$32   ; DRAW_LINE remaining dy for segment 2 (16-bit) (2 bytes)
VLINE_DX_REMAINING   EQU $C880+$34   ; DRAW_LINE remaining dx for segment 2 (16-bit) (2 bytes)
VAR_ARG0             EQU $C880+$36   ; Function argument 0 (16-bit) (2 bytes)
VAR_ARG1             EQU $C880+$38   ; Function argument 1 (16-bit) (2 bytes)
VAR_ARG2             EQU $C880+$3A   ; Function argument 2 (16-bit) (2 bytes)
VAR_ARG3             EQU $C880+$3C   ; Function argument 3 (16-bit) (2 bytes)
VAR_ARG4             EQU $C880+$3E   ; Function argument 4 (16-bit) (2 bytes)
VAR_ARG5             EQU $C880+$40   ; Function argument 5 (16-bit) (2 bytes)
VAR_ARG6             EQU $C880+$42   ; Function argument 6 (16-bit) (2 bytes)
VAR_ARG7             EQU $C880+$44   ; Function argument 7 (16-bit) (2 bytes)
CURRENT_ROM_BANK     EQU $C880+$46   ; Current ROM bank ID (multibank tracking) (1 bytes)
VAR_AUDIO_STARTED    EQU $C880+$47   ; User variable: AUDIO_STARTED (2 bytes)
VAR_VID_FPS          EQU $C880+$49   ; User variable: VID_FPS (2 bytes)
VAR_FRAME            EQU $C880+$4B   ; User variable: FRAME (2 bytes)

;***************************************************************************
; MAIN PROGRAM
;***************************************************************************

MAIN:
    ; Initialize global variables
    CLR VPY_MOVE_X        ; MOVE offset defaults to 0
    CLR VPY_MOVE_Y        ; MOVE offset defaults to 0
    CLR DRAW_VEC_INTENSITY ; 0 = use recorded/vector intensity (no override)
    LDD #0
    STD VAR_AUDIO_STARTED
    LDD #15
    STD VAR_VID_FPS
    ; === Initialize Joystick (one-time setup) ===
    JSR $F1AF    ; DP_to_C8 (required for RAM access)
    CLR $C823    ; CRITICAL: Clear analog mode flag (Joy_Analog does DEC on this)
    LDA #$01     ; CRITICAL: Resolution threshold (power of 2: $40=fast, $01=accurate)
    STA $C81A    ; Vec_Joy_Resltn (loop terminates when B=this value after LSRBs)
    LDA #$01
    STA $C81F    ; Vec_Joy_Mux_1_X (enable X axis reading)
    LDA #$03
    STA $C820    ; Vec_Joy_Mux_1_Y (enable Y axis reading)
    LDA #$00
    STA $C821    ; Vec_Joy_Mux_2_X (disable joystick 2 - CRITICAL!)
    STA $C822    ; Vec_Joy_Mux_2_Y (disable joystick 2 - saves cycles)
    ; Mux configured - J1_X()/J1_Y() can now be called

    ; Prime BIOS button state at startup
    JSR $F1BA    ; Read_Btns: reads PSG reg14 -> $C80F, $C811, $C80E
    ; Call main() for initialization
; VPy_LINE:16
    ; TODO: Statement Pass { source_line: 16 }
    CLR >$C811  ; Force-clear Vec_Buttons before first loop() frame

.MAIN_LOOP:
    JSR LOOP_BODY
    LBRA .MAIN_LOOP   ; Use long branch for multibank support

LOOP_BODY:
    JSR Wait_Recal   ; Synchronize with screen refresh (mandatory)
    JSR $F1BA    ; Read_Btns: PSG reg14 -> $C80F (active-HIGH), edge -> $C811
; VPy_LINE:21
    LDD >VAR_AUDIO_STARTED
    CMPD #0
    LBNE IF_NEXT_1
; VPy_LINE:22
    LDD #1
    STD VAR_AUDIO_STARTED
    LBRA IF_END_0
IF_NEXT_1:
IF_END_0:
; VPy_LINE:28
    LDD >VAR_VID_FPS
    STD VAR_ARG0
    JSR SAMPLE_POS
    STD VAR_FRAME
; VPy_LINE:32
; NATIVE_CALL: DRAW_RECORDING at line 32
    ; DRAW_RECORDING("clip", x, y, scale, frame)
    LDD #0
    TFR B,A          ; X center (low byte)
    STA >DRAW_REC_X
    LDD #0
    TFR B,A          ; Y center (low byte)
    STA >DRAW_REC_Y
    LDD #128
    TFR B,A          ; scale (low byte)
    STA >DRAW_REC_SCALE
    LDD >VAR_FRAME
    STD >DRAW_REC_FRAME
    LDX #_CLIP_VREC      ; recording header
    JSR DRAW_RECORDING_RUNTIME
    LDD #0
    STD RESULT
    RTS

;***************************************************************************
; EMBEDDED ASSETS (vectors, music, levels, SFX)
;***************************************************************************

; --- clip RECORDING (3286 frame(s), fps=15, polyline-chained) ---
