;***************************************************************************
; RUNTIME HELPERS
;***************************************************************************

MUL16:
    ; Signed 16x16->16 multiply: D = X * D (lower 16 bits, sign-correct)
    ; Uses 6809 MUL (8x8->16) for constant-time execution.
    ; Stack after PSHS X,B,A: [SP+0]=A=D_hi=b_hi, [SP+1]=B=D_lo=b_lo,
    ;                         [SP+2]=X_hi=a_hi,  [SP+3]=X_lo=a_lo
    ; Result = a_lo*b_lo + (a_hi*b_lo + a_lo*b_hi)*256  (mod 65536)
    PSHS X,B,A
    ; Step 1: a_lo * b_lo -> 16-bit partial product
    LDA 3,S         ; A = a_lo (X low byte)
    LDB 1,S         ; B = b_lo (D low byte)
    MUL             ; D = a_lo * b_lo (unsigned 16-bit)
    STA TMPPTR      ; TMPPTR   = P0_hi (carry into result bits [15:8])
    STB TMPPTR+1    ; TMPPTR+1 = P0_lo (result bits [7:0])
    ; Step 2: a_hi * b_lo -> only low byte adds to result[15:8]
    LDA 2,S         ; A = a_hi (X high byte)
    LDB 1,S         ; B = b_lo (D low byte)
    MUL             ; D = a_hi * b_lo
    ADDB TMPPTR     ; B += P0_hi (ignore carry = mod 256)
    STB TMPPTR      ; TMPPTR = accumulated result[15:8]
    ; Step 3: a_lo * b_hi -> only low byte adds to result[15:8]
    LDA 3,S         ; A = a_lo (X low byte)
    LDB 0,S         ; B = b_hi (D high byte)
    MUL             ; D = a_lo * b_hi
    ADDB TMPPTR     ; B += accumulated result[15:8] (mod 256)
    TFR B,A         ; A = result_hi
    LDB TMPPTR+1    ; B = result_lo
    LEAS 4,S        ; restore stack
    RTS

MOD16:
    ; Signed 16-bit modulo: D = X % D (result has same sign as dividend)
    ; X = dividend (i16), D = divisor (i16) -> D = remainder
    STD TMPPTR          ; Save divisor
    TFR X,D             ; D = dividend (TFR does NOT set flags!)
    CMPD #0             ; Set flags from FULL D BEFORE any LDA corrupts high byte
    BPL .M16_DPOS       ; if dividend >= 0, skip negation
    COMA
    COMB
    ADDD #1             ; D = |dividend|
    STD TMPVAL          ; store |dividend| BEFORE LDA corrupts A (high byte of D)
    LDA #1
    STA TMPPTR2         ; sign_flag = 1
    BRA .M16_RCHECK
.M16_DPOS:
    STD TMPVAL          ; dividend is positive, store as-is
    LDA #0
    STA TMPPTR2         ; sign_flag = 0 (positive result)
.M16_RCHECK:
    LDD TMPPTR          ; D = divisor
    BPL .M16_RPOS       ; if divisor >= 0, skip negation
    COMA
    COMB
    ADDD #1             ; D = |divisor|
    STD TMPPTR          ; TMPPTR = |divisor|
.M16_RPOS:
.M16_LOOP:
    LDD TMPVAL
    SUBD TMPPTR         ; |dividend| - |divisor|
    BLO .M16_END        ; if |dividend| < |divisor|, done
    STD TMPVAL          ; update remainder
    BRA .M16_LOOP
.M16_END:
    LDD TMPVAL          ; D = |remainder|
    LDA TMPPTR2
    BEQ .M16_DONE       ; zero = positive result
    COMA
    COMB
    ADDD #1             ; negate (same sign as dividend)
.M16_DONE:
    RTS

; ============================================================================
; DRAW_RECORDING_RUNTIME  (.vrec polyline-chained player — single-bank, video-only)
; ============================================================================
DRAW_RECORDING_RUNTIME:
PSHS D,X,Y,U
STX >DRAW_REC_PTR      ; save header base (survives MOD16 / BIOS clobber)
LDD ,X                 ; D = frame_count (FDB, big-endian)
LBEQ DREC_DONE         ; empty recording: nothing to draw
; --- frame_idx = frame % frame_count ---
LDX >DRAW_REC_FRAME    ; X = frame counter (MOD16 dividend)
JSR MOD16              ; D = frame % frame_count (0..frame_count-1)
; --- frame_ptr = offset_table[frame_idx]  (table starts at base+2) ---
LSLB
ROLA                   ; D = frame_idx * 2 (FDB entries)
LDX >DRAW_REC_PTR
LEAX 2,X               ; X = &offset_table[0] (skip frame_count word)
LEAX D,X               ; X = &offset_table[frame_idx]
LDX ,X                 ; X = frame data pointer (absolute)
LDD ,X                 ; D = chain_count
LBEQ DREC_DONE         ; empty frame
STD >DRAW_REC_SEGCNT   ; remaining chains in frame
LEAX 2,X               ; X = first chain header
STX >DRAW_REC_SEGPTR
DREC_CHAIN_LOOP:
; --- scaled+centered start point (DP=$C8), clamped to i8 ---
LDX >DRAW_REC_SEGPTR
LDA ,X                 ; start_x (i8)
LDB >DRAW_REC_X        ; center X (i8)
JSR DREC_COORD         ; B = clamp_i8((start_x*scale>>7) + centerX)
STB >DRAW_REC_SX0
LDX >DRAW_REC_SEGPTR
LDA 1,X                ; start_y
LDB >DRAW_REC_Y
JSR DREC_COORD
STB >DRAW_REC_SY0
; --- intensity: SET_INTENSITY override (DRAW_VEC_INTENSITY) wins if nonzero ---
LDA >DRAW_VEC_INTENSITY
BNE DREC_HAVE_I
LDX >DRAW_REC_SEGPTR
LDA 2,X                ; recorded chain intensity
DREC_HAVE_I:
STA >DRAW_REC_I
; --- seg_count, then advance cursor to first delta ---
LDX >DRAW_REC_SEGPTR
LDB 3,X                ; seg_count (deltas in this chain)
STB >DRAW_REC_CHAIN_SEGS
LEAX 4,X               ; X = first delta (skip start_x,start_y,i,seg_count)
STX >DRAW_REC_SEGPTR
; --- beam setup ONCE per chain (DP=$D0) ---
LDA #$D0
TFR A,DP               ; DP=$D0 for VIA/BIOS access
JSR Reset0Ref          ; once per chain — deltas continue from the endpoint
LDA #$80
STA <$04               ; ACR: SR shift-out (beam control)
LDA >DRAW_REC_I
JSR Intensity_a
LDA >DRAW_REC_SY0      ; A = start Y (Moveto_d absolute: A=Y, B=X)
LDB >DRAW_REC_SX0
JSR Moveto_d
LDA #$C8
TFR A,DP               ; back to DP=$C8 to read/scale deltas
DREC_DELTA_LOOP:
LDB >DRAW_REC_CHAIN_SEGS
LBEQ DREC_CHAIN_NEXT   ; chain done
; scale dx (relative — no center), DP=$C8
LDX >DRAW_REC_SEGPTR
LDA ,X                 ; dx (i8)
JSR DREC_SCALE         ; D = (dx*scale)>>7
JSR DREC_CLAMP8        ; safety clamp (scale<=128 keeps it in range); B = scaled dx
STB >DRAW_REC_SX1
LDX >DRAW_REC_SEGPTR
LDA 1,X                ; dy (i8)
JSR DREC_SCALE
JSR DREC_CLAMP8        ; B = scaled dy
STB >DRAW_REC_SY1
; draw one chained line (DP=$D0) — NO Reset0Ref/Moveto
LDA #$D0
TFR A,DP
LDA >DRAW_REC_SY1      ; A = dy
LDB >DRAW_REC_SX1      ; B = dx
CLR Vec_Misc_Count
JSR Draw_Line_d
LDA #$C8
TFR A,DP               ; back to DP=$C8
; advance to next delta (2 bytes) and decrement delta count
LDX >DRAW_REC_SEGPTR
LEAX 2,X
STX >DRAW_REC_SEGPTR
LDB >DRAW_REC_CHAIN_SEGS
DECB
STB >DRAW_REC_CHAIN_SEGS
LBRA DREC_DELTA_LOOP
DREC_CHAIN_NEXT:
; DRAW_REC_SEGPTR now points at the next chain header (past last delta)
LDD >DRAW_REC_SEGCNT   ; remaining chains
SUBD #1
STD >DRAW_REC_SEGCNT
LBNE DREC_CHAIN_LOOP
DREC_DONE:
LDA #$C8
TFR A,DP               ; ensure DP restored on all exit paths
PULS D,X,Y,U
RTS
; DREC_COORD: A = raw coord (i8), B = center (i8)
;   -> B = clamp_i8((coord*scale>>7) + center). Clobbers A,D,X. DP must be $C8.
DREC_COORD:
PSHS B                 ; save center (i8)
JSR DREC_SCALE         ; D = (coord*scale)>>7 as i16 (already in [-128,127])
STD >DRAW_REC_TMP16
LDB ,S                 ; B = center byte
SEX                    ; D = sign-extended center (i16)
ADDD >DRAW_REC_TMP16   ; D = scaled + center (i16)
JSR DREC_CLAMP8        ; D clamped to [-127,127]; low byte in B
LEAS 1,S               ; drop saved center
RTS
; DREC_CLAMP8: D (i16) -> D clamped to [-127,127] (signed). Low byte usable as i8.
DREC_CLAMP8:
CMPD #127
BLE DREC_CLAMP8_LO
LDD #127
DREC_CLAMP8_LO:
CMPD #-127
BGE DREC_CLAMP8_OK
LDD #-127
DREC_CLAMP8_OK:
RTS
; DREC_SCALE: A = raw coord (i8) -> D = (coord*scale)>>7 as i16 (in [-128,127])
;   scale from DRAW_REC_SCALE (0-128). Clobbers X. DP must be $C8.
DREC_SCALE:
TFR A,B
SEX                    ; D = sign-extended coord (i16)
TFR D,X                ; X = coord (MUL16 operand)
LDB >DRAW_REC_SCALE
CLRA                   ; D = scale (0-128, positive)
JSR MUL16              ; D = coord*scale (signed, fits 16-bit)
ASRA
RORB                   ; >>1 (arithmetic, sign into A)
ASRA
RORB                   ; >>2
ASRA
RORB                   ; >>3
ASRA
RORB                   ; >>4
ASRA
RORB                   ; >>5
ASRA
RORB                   ; >>6
ASRA
RORB                   ; >>7  (D now holds scaled coord, sign-extended in A)
RTS

